import { PrismaClient } from '@prisma/client'

const prisma = new PrismaClient()

const toSlug = (s: string) =>
  s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').substring(0, 80)

function mapType(raw: string): 'INTERNSHIP' | 'PLACEMENT' | 'GRADUATE' | 'SPRING_WEEK' | 'INSIGHT' {
  const t = raw.toLowerCase()
  if (t.includes('insight')) return 'INSIGHT'
  if (t.includes('spring week') || t.includes('spring insight')) return 'SPRING_WEEK'
  if (t.includes('placement') || t.includes('placement year') || t.includes('industrial placement')) return 'PLACEMENT'
  if (
    t.includes('graduate') || t.includes('new grad') || t.includes('grad scheme') ||
    t.includes('analyst programme') || t.includes('apprenticeship')
  ) return 'GRADUATE'
  return 'INTERNSHIP'
}

function parseDeadline(raw: string): Date | null {
  if (!raw || raw.toLowerCase() === 'rolling') return null
  // formats like "31 May 2026", "14 September 2026", "6 October 2026", "29 June 2026"
  const d = new Date(raw)
  if (!isNaN(d.getTime())) return d
  return null
}

function mapWorkMode(location: string): 'REMOTE' | 'HYBRID' | 'ONSITE' {
  const l = location.toLowerCase()
  if (l.includes('remote uk') || l === 'remote') return 'REMOTE'
  if (l.includes('remote')) return 'HYBRID'
  return 'ONSITE'
}

