async function main() {
  console.log(`Seeding ${rows.length} opportunities from CSV…\n`)

  const usedSlugs: Record<string, boolean> = {}
  const existing = await prisma.opportunity.findMany({ select: { slug: true } })
  existing.forEach(o => { usedSlugs[o.slug] = true })

  const today = new Date('2026-05-30')

  let created = 0
  let skipped = 0

  for (const row of rows) {
    const companySlug = toSlug(row.company)

    // Upsert company with logo and website
    const comp = await prisma.company.upsert({
      where: { slug: companySlug },
      update: { website: row.website, logo: row.logo },
      create: { name: row.company, slug: companySlug, website: row.website, logo: row.logo },
    })

    // Generate unique slug
    const baseSlug = toSlug(`${row.company}-${row.title}`)
    let oppSlug = baseSlug
    let n = 2
    while (usedSlugs[oppSlug]) oppSlug = `${baseSlug}-${n++}`
    usedSlugs[oppSlug] = true

    const type = mapType(row.type)
    const deadline = parseDeadline(row.deadline)
    const status = !deadline ? 'OPEN' :
      deadline < today ? 'CLOSED' :
      deadline <= new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000) ? 'CLOSING_SOON' : 'OPEN'

    const workMode = mapWorkMode(row.location)

    try {
      await prisma.opportunity.create({
        data: {
          title: row.title,
          slug: oppSlug,
          description: `${row.title} at ${row.company}. Based in ${row.location}.`,
          type,
          location: row.location,
          workMode,
          deadline,
          startDate: row.startDate || undefined,
          sponsored: false,
          status: status as any,
          applyUrl: row.applyUrl || undefined,
          companyId: comp.id,
        },
      })
      console.log(`✓ [${type}] ${row.company} — ${row.title}`)
      created++
    } catch (e: any) {
      if (e.code === 'P2002') {
        console.log(`  (skip duplicate) ${row.company} — ${row.title}`)
        skipped++
      } else {
        console.error(`✗ ${row.company} — ${row.title}: ${e.message}`)
        skipped++
      }
    }
  }

  console.log(`\nDone! Created: ${created}, Skipped: ${skipped}`)
}

main()
  .catch(console.error)
  .finally(() => prisma.$disconnect())
